-- CAKE2 demo catalogs (documentation/CAKE2, generated by cake_v1_optimization.py): the REAL persons, roles, material and deliverable products, suppliers and the customer
-- that the task lines of cake2_plan_json.json refer to. Idempotent: run it again = the same rows. Run it BEFORE importing the json. Needs start1 + start2 + start4.
DO $$ BEGIN
  IF to_regclass('public."personTable"') IS NULL OR to_regclass('public."rolePriceTable"') IS NULL OR to_regclass('public."productPriceTable"') IS NULL OR to_regclass('public."contractTable"') IS NULL THEN
    RAISE EXCEPTION 'Run start1_sql_tables.sql + start2_sql_code.sql + start4_sql_insert_missing.sql first';
  END IF;
END $$;

BEGIN;
-- managementCalendarTable
ON CONFLICT ("rowGUID") DO UPDATE SET "rowOwnerGUID" = EXCLUDED."rowOwnerGUID", "rowParentGUID" = EXCLUDED."rowParentGUID", "rowJSON" = EXCLUDED."rowJSON";
-- the day rows of those calendars: 2025-12-29 .. 2026-12-31, the hours of the calendar on its working weekdays (Mon = 1 .. Sun = 7 of isodow), 0 on the day off and on Sunday (the plant is closed)
SELECT c.id || ':' || to_char(d, 'YYYY-MM-DD'), c.id, to_char(d, 'YYYY'), (d - DATE '1970-01-01'),
       jsonb_build_object('day', to_char(d, 'YYYY-MM-DD'), 'hours', CASE WHEN (extract(isodow FROM d)::int - 1) = ANY (c.days) THEN c.hours ELSE 0 END,
                          'reason', CASE WHEN (extract(isodow FROM d)::int - 1) = ANY (c.days) THEN 'fill' ELSE 'weekend' END,
                          'isActive', (extract(isodow FROM d)::int - 1) = ANY (c.days))
  FROM (VALUES
  ('ck2-cal-aiko-castillo', 7, ARRAY[1, 2, 3, 4, 5]::int[]),
  ('ck2-cal-elif-novak', 7, ARRAY[0, 1, 2, 3, 4]::int[]),
  ('ck2-cal-ingrid-ziegler', 7, ARRAY[0, 1, 3, 4, 5]::int[]),
  ('ck2-cal-jonas-demir', 7, ARRAY[0, 1, 3, 4, 5]::int[]),
  ('ck2-cal-lena-tanaka', 7, ARRAY[1, 2, 3, 4, 5]::int[]),
  ('ck2-cal-marco-marchetti', 7, ARRAY[0, 1, 2, 3, 4]::int[]),
  ('ck2-cal-priya-santos', 7, ARRAY[0, 2, 3, 4, 5]::int[]),
  ('ck2-cal-tomas-dubois', 7, ARRAY[0, 2, 3, 4, 5]::int[]),
  ('ck2-cal-oskar-veldt', 8, ARRAY[0, 1, 2, 3, 4]::int[]),
  ('ck2-cal-marta-lindqvist', 8, ARRAY[1, 2, 3, 4, 5]::int[]),
  ('ck2-cal-ravi-anand', 8, ARRAY[0, 1, 2, 4, 5]::int[])
  ) AS c(id, hours, days)
  CROSS JOIN generate_series(DATE '2025-12-29', DATE '2026-12-31', INTERVAL '1 day') AS g(d0) CROSS JOIN LATERAL (SELECT g.d0::date AS d) x
ON CONFLICT ("rowGUID") DO UPDATE SET "rowJSON" = EXCLUDED."rowJSON";

-- resourceRoleFolderTable
ON CONFLICT ("rowGUID") DO UPDATE SET "rowOwnerGUID" = EXCLUDED."rowOwnerGUID", "rowParentGUID" = EXCLUDED."rowParentGUID", "rowJSON" = EXCLUDED."rowJSON";

-- resourceRoleTypeTable
ON CONFLICT ("rowGUID") DO UPDATE SET "rowOwnerGUID" = EXCLUDED."rowOwnerGUID", "rowParentGUID" = EXCLUDED."rowParentGUID", "rowJSON" = EXCLUDED."rowJSON";

-- resourceRoleTable
ON CONFLICT ("rowGUID") DO UPDATE SET "rowOwnerGUID" = EXCLUDED."rowOwnerGUID", "rowParentGUID" = EXCLUDED."rowParentGUID", "rowJSON" = EXCLUDED."rowJSON";

-- rolePriceTable
ON CONFLICT ("rowGUID") DO UPDATE SET "rowOwnerGUID" = EXCLUDED."rowOwnerGUID", "rowParentGUID" = EXCLUDED."rowParentGUID", "rowJSON" = EXCLUDED."rowJSON";

-- personTable
ON CONFLICT ("rowGUID") DO UPDATE SET "rowOwnerGUID" = EXCLUDED."rowOwnerGUID", "rowParentGUID" = EXCLUDED."rowParentGUID", "rowJSON" = EXCLUDED."rowJSON";

-- contractTable
ON CONFLICT ("rowGUID") DO UPDATE SET "rowOwnerGUID" = EXCLUDED."rowOwnerGUID", "rowParentGUID" = EXCLUDED."rowParentGUID", "rowJSON" = EXCLUDED."rowJSON";

-- partnerTable
ON CONFLICT ("rowGUID") DO UPDATE SET "rowOwnerGUID" = EXCLUDED."rowOwnerGUID", "rowParentGUID" = EXCLUDED."rowParentGUID", "rowJSON" = EXCLUDED."rowJSON";

-- productFolderTable
ON CONFLICT ("rowGUID") DO UPDATE SET "rowOwnerGUID" = EXCLUDED."rowOwnerGUID", "rowParentGUID" = EXCLUDED."rowParentGUID", "rowJSON" = EXCLUDED."rowJSON";

-- productTypeTable
ON CONFLICT ("rowGUID") DO UPDATE SET "rowOwnerGUID" = EXCLUDED."rowOwnerGUID", "rowParentGUID" = EXCLUDED."rowParentGUID", "rowJSON" = EXCLUDED."rowJSON";

-- productTable
ON CONFLICT ("rowGUID") DO UPDATE SET "rowOwnerGUID" = EXCLUDED."rowOwnerGUID", "rowParentGUID" = EXCLUDED."rowParentGUID", "rowJSON" = EXCLUDED."rowJSON";

-- productPriceTable
ON CONFLICT ("rowGUID") DO UPDATE SET "rowOwnerGUID" = EXCLUDED."rowOwnerGUID", "rowParentGUID" = EXCLUDED."rowParentGUID", "rowJSON" = EXCLUDED."rowJSON";

COMMIT;
NOTIFY pgrst, 'reload schema';

